const AMO_SUBDOMAIN = 'ВАШ-ПОДДОМЕН'; // https://ВАШ-ПОДДОМЕН.amocrm.ru
// Разбор тендера схемы tender.v1, присланного монитором госзакупок.
const b = $input.first().json.body ?? $input.first().json;
const money = (n) => (n == null ? 'не указана' : Number(n).toLocaleString('ru-RU') + ' ' + (b.currency === 'RUB' || !b.currency ? '₽' : b.currency));
const dl = b.deadline_at || null;
let deadlineTs = Math.floor(Date.now() / 1000) + 3 * 86400;
if (dl) {
  const iso = dl.length > 10 ? dl + ':00+03:00' : dl + 'T23:59:00+03:00';
  const t = Date.parse(iso);
  if (!isNaN(t)) deadlineTs = Math.floor(t / 1000);
}
const ai = b.ai || {};
const lines = [
  `Закупка ${b.reg_number} (${b.law}-ФЗ), профиль «${b.profile}»`,
  `Объект: ${b.object}`,
  `Заказчик: ${(b.customer && b.customer.name) || '—'}${b.customer && b.customer.inn ? ', ИНН ' + b.customer.inn : ''}`,
  `Начальная цена: ${money(b.price)}`,
  `Окончание подачи заявок: ${dl || '—'}`,
  `Рейтинг: ${b.rating ?? '—'}`,
];
if (ai.verdict) lines.push(`ИИ (${ai.score ?? '—'}): ${ai.verdict}`);
if (b.user_note) lines.push(`Заметка: ${b.user_note}`);
if (b.url) lines.push(`ЕИС: ${b.url}`);
return [{ json: {
  amo_subdomain: AMO_SUBDOMAIN,
  reg_number: b.reg_number,
  title: `Тендер ${b.reg_number}: ${b.object}`.slice(0, 250),
  object: b.object,
  customer_name: (b.customer && b.customer.name) || '',
  customer_inn: (b.customer && b.customer.inn) || '',
  price: b.price,
  deadline_at: dl,
  deadline_ts: deadlineTs,
  eis_url: b.url || '',
  rating: b.rating,
  note: lines.join('\n'),
  raw: b,
} }];
